// src/middleware/validate.js
'use strict';

const { validationResult } = require('express-validator');

/// Middleware that checks for validation errors generated by express-validator chains.
/// Formats errors consistently with the backend error contract (400 VALIDATION_FAILED)
/// and passes them to next(err) for centralized handling by errorHandler.
function validate(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return next({
      statusCode: 400,
      errorCode: 'VALIDATION_FAILED',
      message: 'Invalid input parameters.',
      details: errors.array().map(err => ({ field: err.path, msg: err.msg }))
    });
  }
  next();
}

module.exports = validate;
